const i={comp7:{t1:"The best trades require research, then commitment.",t2:"Search markets here",t3:"Where global markets live",t4:"Join 50 million traders and investors and take your future into your own hands.",t5:"Explore features",t6:"Market summary",t7:"Highest trading volume",t8:"Popular recommendations",t9:"Market cap ranking",t10:"Why choose us",t11:"Rock-solid security",t12:"Using hot and cold wallet separation technology, a large user protection fund, and strict risk control mechanisms",t13:"Diverse asset selection",t14:"Fast listing of new coins, a wide range of assets, bridging centralized and decentralized markets for one-stop global investment",t15:"Ultra-smooth trading experience",t16:"Top-tier market depth and liquidity, low trading costs, and user-friendly operation",t17:"Fall in love with every",t18:"Trader and investor visiting us each month",t19:"Top website",t20:"Custom scripts and ideas shared by our users",t21:"Trade now"},ieda302:{kaishijiaoyi:"Start Trading",zhunbeihaojiaoyi:"Ready to Trade",cta_miaoshu:"Getting started is quick and easy — even with a small deposit. Complete your application in minutes through our simple onboarding process",gundong:"SCROLL",caidan_shouye:"Home",caidan_shichang:"Markets",caidan_guanyuwomen:"About Us",caidan_tuanduijieshao:"Our Team",caidan_pingtaihegongju:"Platforms & Tools",caidan_jiaoyu:"Education",guanyu_biaoti:"Investor Education & Development Association",guanyu_fubiaoti:"Investor Education & Development Association, IEDA",guanyu_gaikuang:"Overview",guanyu_gaikuang_1:"The Investor Education & Development Association (IEDA) is a nonprofit organization dedicated to enhancing the financial literacy and investment capabilities of everyday investors.",guanyu_gaikuang_2:"IEDA's core mission is to empower investors to make more informed investment decisions through systematic education and the application of advanced tools, thereby reducing risk, improving returns, and promoting the healthy development of financial markets.",guanyu_gaikuang_3:"The association places special emphasis on providing resources to individuals who lack investment experience, helping them understand markets, manage risk, and allocate assets wisely.",guanyu_hexinmubiao:"Core Objectives",guanyu_mubiao1_biaoti:"Enhance Investor Education",guanyu_mubiao1_miaoshu:"Deliver systematic courses, lectures, webinars, and publications covering financial market fundamentals, investment strategies, risk management, and personal financial planning",guanyu_mubiao2_biaoti:"Promote Financial Literacy",guanyu_mubiao2_miaoshu:"Improve public financial literacy so that more people understand the risk-return relationship and strengthen their capacity for rational investing",guanyu_mubiao3_biaoti:"Personalized Financial Planning",guanyu_mubiao3_miaoshu:"Provide customized financial planning services for investors, helping them develop investment strategies based on their individual financial situation and goals",guanyu_mubiao4_biaoti:"Smart Investment Tools & Quantitative Research",guanyu_mubiao4_miaoshu:"Leverage advanced data science, machine learning, and AI tools such as QuantConnect to provide investors with strategy development, backtesting, and automated trading support",guanyu_gongzuolingyu:"Areas of Focus",guanyu_gongzuo1_biaoti:"Investment Education",guanyu_gongzuo1_1:"1. Conduct online courses and offline lectures covering investment instruments including stocks, bonds, funds, futures, forex, and cryptocurrencies.",guanyu_gongzuo1_2:"2. Provide market analysis and investment strategy training to help investors understand market volatility and investment logic.",guanyu_gongzuo1_3:"3. Publish educational materials and guides to systematically promote financial literacy.",guanyu_gongzuo2_biaoti:"Financial Literacy Outreach",guanyu_gongzuo2_1:"1. Organize community events, public lectures, and online seminars to improve public understanding of investing and financial management.",guanyu_gongzuo2_2:"2. Provide introductory education for beginner investors, covering risk management, asset allocation, and financial planning.",guanyu_gongzuo2_3:"3. Advocate rational investment principles to reduce losses caused by uninformed investing.",guanyu_gongzuo3_biaoti:"Personalized Financial Planning Services",guanyu_gongzuo3_1:"1. Provide customized plans based on an investor's income, assets, and goals.",guanyu_gongzuo3_2:"2. Teach how to develop investment plans, diversify risk, and optimize portfolio allocation.",guanyu_gongzuo4_biaoti:"Smart Investment Tools & Quantitative Strategies",guanyu_gongzuo4_1:"1. QuantConnect Integration: IEDA partners with or recommends the QuantConnect platform and its open-source Lean Engine, providing members and students with a quantitative trading development environment.",guanyu_gongzuo4_2:"2. Support multi-asset class strategy development, including stocks, futures, forex, and cryptocurrencies.",guanyu_gongzuo4_3:"3. Utilize data science, machine learning, and AI technologies for strategy backtesting, risk assessment, and automated trading.",guanyu_gongzuo4_4:"4. Encourage investors to combine education with practice, using advanced tools to improve decision quality and investment efficiency.",guanyu_shehuiyingxiang:"Social Impact & Value",guanyu_yingxiang1:"Reduce investment losses among everyday investors caused by information asymmetry or lack of experience",guanyu_yingxiang2:"Promote overall financial literacy across society and increase public confidence in participating in financial markets",guanyu_yingxiang3:"Leverage AI and quantitative technologies to bridge investor education and practice, enabling smarter and more scientific investment approaches",guanyu_yingxiang4:"Foster healthy, transparent, and sustainable development of financial markets",shichang_biaoti:"Trade on Our Platform",shichang_fubiaoti:"From low costs and flexible funding options to choosing the account type that suits you, trading on our platform means you have the freedom to make the most of every market opportunity",shichang_keyonggongju:"Available Instruments",shichang_zhishu_biaoti:"Index CFDs",shichang_zhishu_miaoshu:"Capitalize on volatility across 14 major global markets with commission-free trading.",shichang_jiami_biaoti:"Cryptocurrencies",shichang_jiami_miaoshu:"Trade CFDs on a range of leading cryptocurrencies with high leverage — no digital wallet or exchange required.",shichang_diancha_biaoti:"Spreads & Commissions",shichang_diancha_miaoshu:"Enjoy transparent, competitive round-trip trading costs per lot with low fees and no account charges",shichang_rujin_biaoti:"Deposits & Withdrawals",shichang_rujin_miaoshu:"Wherever you are, we offer free funding methods that work for you. Conveniently manage deposits and withdrawals through your secure workspace",pingtai_biaoti:"Platforms & Tools",pingtai_fubiaoti:"Trade global markets from anywhere with reliable platforms and fast execution",pingtai_womendepingtai:"Our Platforms",pingtai_miaoshu:"Enjoy the freedom to trade — wherever you are. Our platform is available on desktop for Windows and Mac OS, and on mobile devices and tablets for iOS and Android.",pingtai_anzhuo:"Android",pingtai_saomaxiazai:"Scan to download",pingtai_lianxikefu:"Contact support for the download link",pingtai_fayoujian:"Email us at",pingtai_huoqulianjie:"Get download link",pingtai_jiaoyigongju:"Trading Tools",pingtai_smarttrader_biaoti:"SmartTrader Tools for Comprehensive Markets",pingtai_smarttrader_miaoshu:"Optimize your trading strategy and enhance your experience with 28 tools and indicators",pingtai_autochartist_biaoti:"Autochartist",pingtai_autochartist_miaoshu:"Discover a wealth of trading opportunities through powerful trend recognition tools and key support and resistance level analysis",pingtai_jiaoyihuoban:"Our Social Trading Partners",pingtai_myfxbook_miaoshu:"Myfxbook is an online automated analysis tool for your forex trading account and a social forex community. Copy trades from the Myfxbook AutoTrade system directly to your account.",pingtai_metatrader_biaoti:"MetaTrader Signals",pingtai_metatrader_miaoshu:"MT4 Signals enable you to automatically copy trading operations in real time. You can intervene at any time to close trades, adjust capital allocation, update stop-losses, or remove strategies.",pingtai_duplitrade_miaoshu:"DupliTrade offers an advanced automated mirror trading system. By copying trades from carefully selected traders, you can automate your forex, index, and commodity trading.",jiaoyu_biaoti:"Education",jiaoyu_fubiaoti_1:"We provide a wealth of online resources, trading guides, and expert webinars in English.",jiaoyu_fubiaoti_2:"If you would like to learn more or are looking for specific information, please contact us",jiaoyu_jiaoyizhinan:"Trading Guides",jiaoyu_zhinan1_biaoti:"11 Tips to Improve Expert Advisor (EA) Performance",jiaoyu_zhinan1_miaoshu:"For many forex traders, an EA represents the culmination of countless hours spent crafting an automated version of their own trading strategy.",jiaoyu_zhinan2_biaoti:"Survival Rules in High-Volatility Market Conditions",jiaoyu_zhinan2_miaoshu:"When facing the dual challenges of high leverage and high volatility in financial markets, it is essential to adjust your trading strategy accordingly — otherwise you risk margin calls or significant losses.",jiaoyu_zhinan3_biaoti:"Why Do Spreads Widen",jiaoyu_zhinan3_miaoshu:"We understand that trading costs are a top concern for our clients, which is why we are committed to offering industry-competitive spreads. By connecting with leading investment banks and liquidity providers, we ensure the best possible...",jiaoyu_zhinan4_biaoti:"Limit Up & Limit Down",jiaoyu_zhinan4_miaoshu:"Due to circuit breaker mechanisms — commonly known as limit up and limit down rules — trading is temporarily halted when stocks or indices experience extreme moves. Investors can use this pause to reassess current market conditions.",jiaoyu_zhinan5_biaoti:"Volatility Index (VIX)",jiaoyu_zhinan5_miaoshu:"Volatility plays a significant role in the markets. Whether traders use manual trading strategies or execute trades through automated algorithms, volatility is a core element of the financial markets.",jiaoyu_zhinan6_biaoti:"What Type of Trader Are You?",jiaoyu_zhinan6_miaoshu:"From Buzzy Schwartz to Ray Dalio, the great figures of the trading industry have vastly different characteristics. Which type are you?",tuandui_biaoti:"Our Team",tuandui_shouxifenxishi:"Chief Analyst",tuandui_shouxiguwen:"Chief Investment Advisor",tuandui_gerenjianjie:"Biography",tuandui_jiaoyubeijing:"Education",tuandui_zhiyelvli:"Career History",tuandui_hangyebiaozhun:"Industry Standards & Policy Advisory",tuandui_xueshuzhuzuo:"Academic & Published Works",tuandui_shehuiyingxiangli:"Social Impact",tuandui_hexinyewu:"Core Business Areas",tuandui_hexinlinian:"Core Philosophy",tuandui_gerenlinian:"Personal Philosophy",tuandui_zhongyaorongyu:"Key Honors",tuandui_hexinzizhi:"Core Professional Credentials",tuandui_hexinnengli:"Core Competencies",tuandui_hangyegongxian:"Industry Contributions & Honors",tuandui_fx_org:"Investor Education & Development Association (IEDA)",tuandui_fx_name:"Jonathan Hargrave",tuandui_fx_role:"IEDA Founder & Chief Executive Officer",tuandui_fx_location:"Based in: Wall Street, New York, USA",tuandui_fx_bio1:"Jonathan Hargrave is an authoritative figure in global financial investment education and a seasoned financial professional with over 30 years of frontline investment and wealth management experience on Wall Street.",tuandui_fx_bio2:"Following the 2008 global financial crisis, he identified the critical industry pain points of insufficient financial literacy and inadequate risk awareness among everyday investors. In 2010, he formally established the Investor Education & Development Association (IEDA) on Wall Street, New York, as a 501(c)(3) nonprofit organization, building an inclusive financial education platform for everyday investors worldwide.",tuandui_fx_bio3:'For over a decade, guided by the mission of "breaking down the knowledge barriers between Wall Street and everyday investors," he has led IEDA to serve more than 5 million investors globally, developing comprehensive courses and tools spanning all areas of finance, and advancing the standardization of global investor education.',tuandui_fx_bio4:"He also serves as a lifetime member of the Financial Planning Association (FPA), an Investor Education Advisor to the New York Stock Exchange (NYSE), and has been invited multiple times to testify before the U.S. Congressional hearings on financial consumer protection, providing core expert advice for the development of global investor protection policies.",tuandui_fx_edu1:"Bachelor of Science in Finance, NYU Stern School of Business, honors graduate, GPA 3.9/4.0; President of the university's Investment Club, leading the student investment fund to an annualized return of 15%.",tuandui_fx_edu2:"MBA from Columbia Business School, with a core focus on Wealth Management and Behavioral Finance; thesis awarded the annual Outstanding Thesis Award.",tuandui_fx_edu3:"Completed CFA, FRM, and CFP professional certifications, earning the designations of Chartered Financial Analyst, Financial Risk Manager, and Certified Financial Planner.",tuandui_fx_huaerjie:"Wall Street Frontline Experience",tuandui_fx_huaerjie_nianfen:"(1992–2010)",tuandui_fx_ieda_chuangli:"IEDA Founding & Development",tuandui_fx_ieda_nianfen:"(2010–Present)",tuandui_fx_ws1_company:"Morgan Stanley",tuandui_fx_ws1_role:"Institutional Investment Division · Analyst",tuandui_fx_ws2_company:"Goldman Sachs",tuandui_fx_ws2_role:"Wealth Management Division · Vice President",tuandui_fx_ws3_company:"Citigroup",tuandui_fx_ws3_role:"Global Retail Banking Division · Managing Director",tuandui_fx_dev1_company:"Initial Stage",tuandui_fx_dev1_role:"New York headquarters launched",tuandui_fx_dev2_company:"Digital Transformation",tuandui_fx_dev2_role:"Users surpassed one million",tuandui_fx_dev3_company:"Global Expansion",tuandui_fx_dev3_role:"Industry benchmark",tuandui_fx_dev4_company:"Digital Upgrade",tuandui_fx_dev4_role:"Ecosystem buildout",tuandui_fx_policy1_biaoti:"Industry Standards Development",tuandui_fx_policy1_miaoshu:"Led the drafting of the U.S. Retail Investor Education Industry Standards, which became a core reference standard for FINRA's investor education services.",tuandui_fx_policy2_biaoti:"Congressional Testimony",tuandui_fx_policy2_miaoshu:"Invited 5 times to testify before the U.S. Congressional Financial Services Committee on topics including the Dodd-Frank Act investor protection provisions and retail investor rights protection, contributing to the enactment of multiple policies.",tuandui_fx_policy3_biaoti:"Global Standards Development",tuandui_fx_policy3_miaoshu:"Participated in developing the core guidelines of the Global Investor Education Alliance (GIEA), covering 30+ countries and promoting the standardization and accessibility of global financial education.",tuandui_fx_pub1_label:"01 — Financial Literacy Books Global Sales",tuandui_fx_pub1_unit:"million copies",tuandui_fx_pub1_miaoshu:'Published 12 financial literacy books including "The Everyday Investor\'s Guide" and "Financial Risk Perception & Decision-Making," with cumulative global sales exceeding 2 million copies. Multiple titles adopted as financial literacy textbooks by leading universities.',tuandui_fx_pub2_label:"02 — Investment Articles in Top Media",tuandui_fx_pub2_unit:"articles",tuandui_fx_pub2_miaoshu:"Maintains regular columns in The Wall Street Journal and Financial Times, with over 500 investor education articles published and a cumulative readership exceeding 100 million views.",tuandui_fx_pub3_label:"03 — Financial Education Professionals Trained",tuandui_fx_pub3_unit:"professionals",tuandui_fx_pub3_miaoshu:"Serves as a visiting professor at NYU Stern School of Business and Columbia Business School, having trained over 500 financial education professionals.",tuandui_fx_social1_biaoti:"Global Financial Literacy Initiative",tuandui_fx_social1_unit:"developing countries",tuandui_fx_social1_miaoshu:"Led IEDA's Global Financial Literacy Initiative, reaching over 100 developing countries and helping more than one million low-income investors establish foundational investment knowledge.",tuandui_fx_social2_biaoti:"Investor Rights Protection Program",tuandui_fx_social2_unit:"individuals served",tuandui_fx_social2_miaoshu:'Launched the Investor Rights Protection Program, providing free investment consultation and risk assessment for underserved communities. Over 100,000 individuals served to date, earning the United Nations "Global Best Practice in Public Service" designation.',tuandui_fx_biz1_biaoti:"Investment Education",tuandui_fx_biz1_miaoshu:"Provide investors with comprehensive education in financial fundamentals, investment strategies, market analysis, and personal financial planning through online courses, offline lectures, webinars, and publications.",tuandui_fx_biz2_biaoti:"Financial Literacy Outreach",tuandui_fx_biz2_miaoshu:"Focused on improving public financial literacy, helping everyday investors understand financial markets, products, and risks — with priority service for beginner investors and underserved communities.",tuandui_fx_biz3_biaoti:"Personalized Financial Planning",tuandui_fx_biz3_miaoshu:"Deliver tailored financial planning and investment solutions based on users' financial situations and goals for precision empowerment.",tuandui_fx_biz4_biaoti:"Smart Investment Tools",tuandui_fx_biz4_miaoshu:"Develop AI-driven investment analysis and risk assessment tools to lower the barrier to entry for investors and optimize decision-making efficiency.",tuandui_fx_prin1_biaoti:"Inclusive Finance",tuandui_fx_prin1_miaoshu:"Enable everyday investors to access professional, unbiased, and accessible financial education and investment tools.",tuandui_fx_prin2_biaoti:"Risk First",tuandui_fx_prin2_miaoshu:"Establish risk awareness before discussing returns and strategies — oppose emotional and herd-mentality investing.",tuandui_fx_prin3_biaoti:"Long-Term Vision",tuandui_fx_prin3_miaoshu:"Replace short-term speculative impulses with systematic knowledge, disciplined execution, and asset allocation thinking.",tuandui_fx_prin4_biaoti:"Tool Equality",tuandui_fx_prin4_miaoshu:"Democratize AI and quantitative capabilities for everyday investors, closing the capability gap between institutional and individual investors.",tuandui_fx_quote:"Finance was never meant to be a game for the few. Every individual deserves access to professional, unbiased financial education and the means to achieve steady wealth growth through scientific investing. I founded IEDA with one purpose — to tear down the wall between Wall Street and everyday investors, turning financial knowledge into a tool everyone can master, not a weapon wielded by the privileged few.",tuandui_fx_cfa_nianfen:"Certified in 1998",tuandui_fx_cfa_biaoti:"Chartered Financial Analyst",tuandui_fx_cfa_miaoshu:"Chartered Financial Analyst (CFA) charterholder (1998).",tuandui_fx_frm_nianfen:"Certified in 2000–2002",tuandui_fx_frm_biaoti:"Financial Risk Manager / Certified Financial Planner",tuandui_fx_frm_miaoshu:"Financial Risk Manager (FRM, 2002) charterholder, Certified Financial Planner (CFP, 2000) designee.",tuandui_fx_series_nianfen:"New York State Securities Licenses",tuandui_fx_series_biaoti:"New York State Securities Licenses",tuandui_fx_series_miaoshu:"New York State Securities License holder (Series 7/66).",tuandui_fx_honor1_biaoti:"Annual Leader in Financial Education",tuandui_fx_honor1_org:"Financial Planning Association (FPA)",tuandui_fx_honor2_biaoti:"Outstanding Contribution to Investor Protection",tuandui_fx_honor2_org:"New York Stock Exchange (NYSE)",tuandui_fx_honor3_biaoti:"Lifetime Achievement in Investor Education",tuandui_fx_honor3_org:"U.S. Securities and Exchange Commission (SEC)",tuandui_fx_honor4_biaoti:"Inclusive Finance Promoter",tuandui_fx_honor4_org:"Global Finance Forum",tuandui_fx_honor5_biaoti:"Global Public Welfare Model",tuandui_fx_honor5_org:"United Nations Economic and Social Council",tuandui_gw_org:"Investor Education & Development Association (IEDA)",tuandui_gw_name:"Helena Whitmore",tuandui_gw_role:"—— IEDA Financial Investment Education, Founder's Assistant & Chief Investment Advisor",tuandui_gw_location:"Based in: New York, USA",tuandui_gw_bio:"With 12 years of experience in Wall Street financial markets, Helena specializes in equity investment, asset allocation, and investor education, combining frontline trading expertise with the ability to build comprehensive investor education systems. She currently serves as a core assistant to the founder of a leading New York financial investment education institution and as Chief Investment Advisor, providing customized investment strategies for high-net-worth individuals, family offices, and institutional clients. She leads the development of investor education curricula and end-to-end client asset planning services, having served over 500 clients with assets under management exceeding $280 million. Her portfolios have consistently outperformed the S&P 500 with an annualized return of 12.7%.",tuandui_gw_edu1:"Bachelor of Science in Finance, Wharton School, University of Pennsylvania (GPA 3.9/4.0, Honors Graduate)",tuandui_gw_edu1_d1:"Core Focus: Investment Studies, Financial Markets, Quantitative Analysis",tuandui_gw_edu1_d2:"Honors: Phi Beta Kappa Member, Wharton School Distinguished Graduate",tuandui_gw_edu2:"Master of Science in Finance, Columbia Business School",tuandui_gw_edu2_d1:"Core Focus: Asset Management, Derivatives Pricing, Behavioral Finance",tuandui_gw_edu2_d2:"Project: Core Member of the Columbia University Global Financial Markets Research Program",tuandui_gw_career1_company:"Goldman Sachs",tuandui_gw_career1_role:"Investment Research Division · Financial Analyst",tuandui_gw_career2_company:"Morgan Stanley",tuandui_gw_career2_role:"Wealth Management Division · Senior Investment Advisor",tuandui_gw_career3_company:"IEDA Financial Investment Education",tuandui_gw_career3_role:"Founder's Assistant & Chief Investment Advisor",tuandui_gw_comp1_biaoti:"Investment Expertise",tuandui_gw_comp1_1:"Deep expertise across global financial markets including U.S. equities, cryptocurrencies, global equities, fixed income, and alternative assets, with strengths in macroeconomic trend analysis, sector cycle evaluation, and in-depth equity research",tuandui_gw_comp1_2:"Proficient in asset allocation models and quantitative investment tools, capable of designing personalized investment solutions based on client risk appetite and life-stage considerations",tuandui_gw_comp1_3:"Extensive hands-on trading experience with thorough knowledge of U.S. equity trading rules and derivatives instruments, providing clients with real-time trading guidance",tuandui_gw_comp2_biaoti:"Education & Management Skills",tuandui_gw_comp2_1:"Expert in building investor education frameworks, skilled at transforming complex financial knowledge into accessible course content, with outstanding curriculum development and teaching capabilities",tuandui_gw_comp2_2:"Exceptional team management and project coordination skills, capable of leading teams across investment research, client services, and curriculum development",tuandui_gw_comp2_3:"Strong high-net-worth client relationship management skills, adept at identifying client needs and building long-term trusted partnerships",tuandui_gw_comp3_biaoti:"Languages & Other Skills",tuandui_gw_comp3_1:"English: Native proficiency, fluent in financial terminology",tuandui_gw_comp3_2:"German: Fluent (business communication level), able to deliver investor education services in German",tuandui_gw_comp3_3:"Proficient in Bloomberg Terminal, Wind, FactSet, Python, SQL, and other financial and data analysis tools",tuandui_gw_honor1_nianfen:"2022",tuandui_gw_honor1_biaoti:"Outstanding Investor Education Practitioner of the Year",tuandui_gw_honor1_org:"Global Investor Education Alliance",tuandui_gw_honor2_nianfen:"2023",tuandui_gw_honor2_biaoti:"Outstanding Young Investment Advisor of the Year",tuandui_gw_honor2_org:"New York Financial Association"}};export{i as default};
